SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, drug_indication.efo_id AS indication_curie, drug_indication.efo_term AS indication_label, drug_indication.max_phase_for_ind FROM molecule_dictionary JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE drug_indication.efo_term = 'Chronic kidney disease' AND molecule_dictionary.max_phase = 4 ORDER BY molecule_dictionary.chembl_id ASC, molecule_dictionary.pref_name ASC, compound_structures.canonical_smiles ASC, indication_curie ASC, indication_label ASC, drug_indication.max_phase_for_ind ASC
